ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS tracking_number text;
CREATE OR REPLACE FUNCTION public.require_active_account() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND status='active') THEN RAISE EXCEPTION 'Your account is not active'; END IF; END $$;
REVOKE ALL ON FUNCTION public.require_active_account() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.require_active_account() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,email) VALUES(new.id,new.email); INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'customer'); RETURN new; END $$;
ALTER FUNCTION public.auto_confirm_new_user() SET search_path=public;
CREATE OR REPLACE FUNCTION public.protect_profile_status() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(),'admin') THEN new.status:=old.status; END IF; RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.cancel_my_checkout(_checkout uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o record; BEGIN PERFORM public.require_active_account(); FOR o IN SELECT id FROM public.orders WHERE checkout_id=_checkout AND customer_id=auth.uid() AND status='pending_payment' ORDER BY id FOR UPDATE LOOP IF EXISTS(SELECT 1 FROM public.orders WHERE id=o.id AND status='pending_payment') THEN UPDATE public.orders SET status='cancelled' WHERE id=o.id; UPDATE public.product_variants v SET stock=v.stock+i.quantity FROM public.order_items i WHERE i.order_id=o.id AND i.variant_id=v.id; END IF; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.simulate_payment(_checkout uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.require_active_account(); PERFORM id FROM public.orders WHERE checkout_id=_checkout AND customer_id=auth.uid() ORDER BY id FOR UPDATE; IF NOT EXISTS(SELECT 1 FROM public.orders WHERE checkout_id=_checkout AND customer_id=auth.uid() AND status='pending_payment') THEN RAISE EXCEPTION 'No unpaid order found'; END IF; UPDATE public.orders SET status='paid',paid_at=now() WHERE checkout_id=_checkout AND customer_id=auth.uid() AND status='pending_payment'; END $$;
CREATE OR REPLACE FUNCTION public.update_order_status(_order uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; BEGIN PERFORM public.require_active_account(); SELECT * INTO o FROM public.orders WHERE id=_order FOR UPDATE; IF o.id IS NULL OR NOT(public.owns_store(o.store_id) OR public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Not allowed'; END IF; IF NOT((o.status='pending_payment' AND _status='cancelled') OR (o.status='paid' AND _status IN ('processing','cancelled')) OR (o.status='processing' AND _status IN ('shipped','cancelled')) OR (o.status='shipped' AND _status='completed')) THEN RAISE EXCEPTION 'Invalid order transition'; END IF; IF _status='shipped' AND nullif(trim(o.tracking_number),'') IS NULL AND o.courier<>'pickup' THEN RAISE EXCEPTION 'Add a tracking number before shipping'; END IF; UPDATE public.orders SET status=_status WHERE id=_order; IF _status='cancelled' THEN UPDATE public.product_variants v SET stock=v.stock+i.quantity FROM public.order_items i WHERE i.order_id=_order AND i.variant_id=v.id; END IF; END $$;
CREATE OR REPLACE FUNCTION public.ship_order(_order uuid,_tracking text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; BEGIN PERFORM public.require_active_account(); SELECT * INTO o FROM public.orders WHERE id=_order FOR UPDATE; IF o.id IS NULL OR NOT(public.owns_store(o.store_id) OR public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Not allowed'; END IF; IF length(trim(coalesce(_tracking,'')))<3 OR length(_tracking)>120 THEN RAISE EXCEPTION 'Enter a tracking number between 3 and 120 characters'; END IF; UPDATE public.orders SET tracking_number=trim(_tracking) WHERE id=_order; PERFORM public.update_order_status(_order,'shipped'); END $$;
REVOKE ALL ON FUNCTION public.ship_order(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.ship_order(uuid,text) TO authenticated,service_role;
DO $$ DECLARE f record; BEGIN FOR f IN SELECT oid::regprocedure AS name,proname FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('handle_new_user','auto_confirm_new_user','protect_profile_status','protect_store_status','check_checkout_stock','become_seller','cancel_my_checkout','simulate_payment','place_order','update_order_status','has_role','owns_store') LOOP EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC,anon',f.name); IF f.proname IN ('become_seller','cancel_my_checkout','simulate_payment','place_order','update_order_status','has_role','owns_store') THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated,service_role',f.name); ELSE EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM authenticated',f.name); END IF; END LOOP; END $$;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role),public.owns_store(uuid) TO anon;
